# Rebuild deterministic numerical fixtures using the unmodified pinned upstream package.
# Run from the splines2 package directory: Rscript tools/generate_reference.R
library(splines2)
stopifnot(as.character(packageVersion('splines2')) == '0.5.4')
options(splines2.warn.outside = FALSE, digits = 17)
con <- file('test/reference.dat', 'wt')
on.exit(close(con))
writeLines(c('# splines2 0.5.4 CRAN pin 2321fc1788c387ad06e531d408c31b5d840b2286',
             '# R 4.5.0; rows stored in column-major order; generated by tools/generate_reference.R'), con)
count <- 0L
emit <- function(family, degree, derivs, integral, intercept, periodic, scale,
                 knots, x, bounds = c(0, 1)) {
    fun <- list(bSpline, mSpline, iSpline, cSpline, naturalSpline, nsk, bernsteinPoly)[[family]]
    args <- list(x = x, intercept = intercept, Boundary.knots = bounds, derivs = derivs)
    if (family %in% c(1:4, 7)) args$degree <- degree
    if (family != 7) args$knots <- knots
    if (family %in% c(1, 2)) args$periodic <- periodic
    if (family %in% c(1, 2, 5, 6, 7)) args$integral <- integral
    if (family == 4) args$scale <- scale
    # Upstream 0.5.4 scales the reduced C derivative by a full-width vector,
    # causing an Armadillo shape error. Reference the full result then drop
    # its first column for this explicitly documented bug repair.
    if (family == 4 && scale && !intercept && derivs > 0) {
        args$intercept <- TRUE
        ans <- do.call(fun, args)[, -1, drop = FALSE]
    } else ans <- do.call(fun, args)
    count <<- count + 1L
    writeLines(sprintf('%d %d %d %d %d %d %d', family, degree, derivs,
                       integral, intercept, periodic, scale), con)
    writeLines(sprintf('%d %d %d', length(x), length(knots), ncol(ans)), con)
    writeLines(paste(format(bounds, scientific = TRUE, digits = 17), collapse = ' '), con)
    writeLines(paste(format(x, scientific = TRUE, digits = 17), collapse = ' '), con)
    if (length(knots)) writeLines(paste(format(knots, scientific = TRUE, digits = 17), collapse = ' '), con)
    for (j in seq_len(ncol(ans))) writeLines(paste(format(ans[,j], scientific = TRUE, digits = 17), collapse = ' '), con)
}
x <- c(-0.3, 0, 0.03, 0.2, 0.35, 0.5, 0.75, 0.9, 1, 1.2)
for (family in 1:4) for (degree in 0:5) for (derivs in unique(c(0:3, degree+1, degree+2, degree+3))) {
    for (intercept in c(TRUE, FALSE)) {
        emit(family, degree, derivs, FALSE, intercept, FALSE, TRUE, c(0.2, 0.5, 0.9), x)
        if (family %in% 1:2) emit(family, degree, derivs, TRUE, intercept, FALSE, TRUE, c(0.2,0.5,0.9), x)
        if (family == 4) emit(family, degree, derivs, FALSE, intercept, FALSE, FALSE, c(0.2,0.5,0.9), x)
    }
}
for (family in 1:2) for (degree in 0:5) for (derivs in c(0, 1, 2, 6)) for (integral in c(FALSE, TRUE)) {
    kk <- seq(0, 1, length.out = max(degree, 4) + 1)[-c(1,max(degree,4)+1)]
    emit(family, degree, derivs, integral, TRUE, TRUE, TRUE, kk, c(-2.25,-0.25,0,0.23,0.5,0.999,1,1.25,3.75))
}
for (family in 5:6) for (nk in 0:5) for (derivs in 0:5) for (integral in c(FALSE,TRUE)) {
    kk <- if (nk) seq(0,1,length.out=nk+2)[-c(1,nk+2)] else numeric()
    for (intercept in c(FALSE,TRUE)) emit(family,3,derivs,integral,intercept,FALSE,TRUE,kk,x)
}
for (degree in 0:10) for (derivs in unique(c(0,1,2,degree,degree+1))) for (integral in c(FALSE,TRUE)) {
    emit(7,degree,derivs,integral,TRUE,FALSE,TRUE,numeric(),c(0,0.01,0.2,0.5,0.99,1))
}
# Unequal intervals and non-unit bounds for natural and periodic cases.
for (family in 1:6) {
    emit(family,3,0,FALSE,TRUE,FALSE,TRUE,c(2.7,3.5,6.2),c(1,2,2.8,4,6.5,7,8),c(2,7))
}
for (family in 1:2) for (derivs in 0:3) for (integral in c(FALSE,TRUE)) {
    emit(family,3,derivs,integral,FALSE,TRUE,TRUE,c(2.7,3.5,6.2),c(-8,2,2.8,4,6.5,7,8,14),c(2,7))
}
# Repeated knots through full order, including evaluation at the repeated knot.
for (family in 1:4) for (degree in 1:5) for (mult in 2:(degree+1)) for (derivs in 0:2) {
    emit(family,degree,derivs,FALSE,TRUE,FALSE,TRUE,c(rep(0.2,mult),0.5,0.9),x)
}
close(con)
cat(count, 'reference cases generated\n')
